<script setup lang="ts">
import { computed, ref } from 'vue';
import { state, scope, ui, replace } from '../state';
import { applyDataset, applyWorkbook, checkpoint, clone, exportApplication, type Checkpoint } from '../services/application-state';
import { decodeFile, downloadFile, encodeFile } from '../services/data-files';
import { recoveryImportPreview, type RecoveryDelta } from '../services/recovery-preview';
import { parseCubWorkbook, validateWorkbookPreview, type WorkbookPreviewData, type WorkbookLike } from '../features/workbook/workbook-parser';
import WorkbookImportPreview from '../features/workbook/WorkbookImportPreview.vue';
import { LEGACY_KEYS } from '../services/legacy-state';
import type { ImportKind } from '../services/import-validation';
const kinds:ImportKind[]=['full','requirements','progress','activities','schedule','trees'];
const kind=ref<ImportKind>('full'),format=ref('json'),pending=ref<{kind:ImportKind;data:unknown;delta:RecoveryDelta;name:string;baseline:string}|null>(null),workbook=ref<WorkbookPreviewData|null>(null),workbookName=ref(''),workbookBaseline=ref(''),revision=ref(0),reset=ref(''),confirmation=ref('');
const checkpoints=computed(()=>{void revision.value;try{const value=JSON.parse(localStorage.getItem(LEGACY_KEYS.checkpoints)??'[]');return Array.isArray(value)?value as Checkpoint[]:[];}catch{return [];}});
function exportData(k:ImportKind){try{downloadFile('oas-'+k+'.'+format.value,encodeFile(k,exportApplication(state.value!,k,scope.value),format.value));}catch(e){ui.error=String(e);}}
function preview(k:ImportKind,data:unknown,name:string){try{pending.value={kind:k,data,delta:recoveryImportPreview(k,exportApplication(state.value!,k,scope.value),data,state.value!.requirements),name,baseline:JSON.stringify(state.value)};workbook.value=null;}catch(e){ui.error=String(e);}}
async function importFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{preview(kind.value,decodeFile(kind.value,await file.text(),file.name),file.name);}catch(e){ui.error=String(e);}input.value='';}
function apply(){if(!pending.value)return;if(pending.value.baseline!==JSON.stringify(state.value)){ui.error='Data changed after preview. Choose the file again.';return;}try{if(replace('Before importing '+pending.value.kind,applyDataset(state.value!,pending.value.kind,pending.value.data))){pending.value=null;revision.value++;}}catch(e){ui.error=String(e);}}
async function importWorkbook(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const XLSX=await import('xlsx');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,cellStyles:true});workbook.value=validateWorkbookPreview(parseCubWorkbook(wb as unknown as WorkbookLike,XLSX,state.value!.requirements));workbookName.value=file.name;workbookBaseline.value=JSON.stringify(state.value);pending.value=null;}catch(e){ui.error=String(e);}input.value='';}
function applyBook(){if(!workbook.value)return;if(workbookBaseline.value!==JSON.stringify(state.value)){ui.error='Data changed after workbook preview. Import again.';return;}if(replace('Before workbook import',applyWorkbook(state.value!,workbook.value))){workbook.value=null;revision.value++;}}
function manualCheckpoint(){try{checkpoint(localStorage,state.value!,'Manual checkpoint');revision.value++;ui.notice='Checkpoint saved locally';}catch(e){ui.error=String(e);}}
async function applyReset(){if(confirmation.value!=='RESET')return;const next=clone(state.value!);try{
 if(reset.value==='achievements')for(const [key,record] of Object.entries(next.progress.scoutRecords))if(!key.endsWith('::__roster__'))next.progress.scoutRecords[key]={...record,completed:false,date:'',sessionEvidence:[],occurrences:0};
 if(reset.value==='scouts'||reset.value==='factory')next.progress.scoutRecords={};
 if(reset.value==='schedule'||reset.value==='factory')next.studio.schedule=[];
 if(reset.value==='requirements'||reset.value==='factory'){const r=await fetch(new URL('data/requirements.json',document.baseURI));if(!r.ok)throw new Error('Default curriculum could not be loaded');next.requirements=(await r.json()).requirements;}
 if(reset.value==='factory'){next.progress.activities=[];next.studio={trees:[],order:{},tags:[],schedule:[],history:[],treeGraphs:{},strategy:'progress',weeks:40,capacity:4};}
 if(replace('Before reset: '+reset.value,next)){reset.value='';confirmation.value='';revision.value++;}
 }catch(e){ui.error=String(e);}}
</script>
<template><section><article class="panel"><h2>1. Current state</h2><p>{{state!.requirements.length}} requirements · {{Object.keys(state!.progress.scoutRecords).length}} evidence / roster records · {{state!.progress.activities?.length??0}} activities · {{state!.studio.schedule?.length??0}} scheduled weeks.</p><p>Imports and edits create safety checkpoints before changing data. Full JSON or YAML backups preserve nested evidence and editor metadata.</p><button @click="manualCheckpoint">Save checkpoint</button></article>
 <article class="panel"><h2>2. Importer</h2><label>Dataset<select v-model="kind"><option v-for="k in kinds" :key="k">{{k}}</option></select></label><label>Choose JSON / YAML / OAS CSV<input type="file" accept=".json,.yaml,.yml,.csv" @change="importFile"></label><label>Original Scout progress workbook<input type="file" accept=".xlsx,.xls,.xlsm" @change="importWorkbook"></label><section v-if="pending" class="preview"><h3>Review {{pending.kind}} import</h3><p>{{pending.name}}</p><p>{{pending.delta.added}} added · {{pending.delta.modified}} modified · {{pending.delta.removed}} removed</p><p>{{pending.delta.description}}</p><button @click="apply">Apply import</button><button @click="pending=null">Cancel</button></section><section v-if="workbook" class="preview"><WorkbookImportPreview :filename="workbookName" :preview="workbook" :on-apply="applyBook" :on-cancel="()=>workbook=null" /></section></article>
 <article class="panel"><h2>3. Exporter</h2><label>Export format<select v-model="format"><option value="json">JSON</option><option value="yaml">YAML</option><option value="csv">OAS CSV</option></select></label><div class="toolbar"><button v-for="k in kinds" :key="k" @click="exportData(k)">Export {{k}}</button></div></article>
 <article class="panel"><h2>4. Recovery and reset</h2><p>Six full safety checkpoints are retained locally. Download a full backup for longer retention.</p><div v-for="(c,i) in checkpoints" :key="i" class="toolbar"><span>{{c.title}} · {{c.at}}</span><button @click="preview('full',c.payload,'Checkpoint: '+c.title)">Review restore</button></div><label>Reset operation<select v-model="reset"><option value="">Choose operation</option><option value="achievements">Clear achievements only</option><option value="scouts">Clear roster and achievements</option><option value="schedule">Clear schedule</option><option value="requirements">Restore default requirements</option><option value="factory">Factory reset</option></select></label><form v-if="reset" @submit.prevent="applyReset"><p>This changes local {{reset}} data. A full checkpoint is saved first. Export a full backup before proceeding.</p><label>Type RESET to apply<input v-model="confirmation"></label><button :disabled="confirmation!=='RESET'">Apply reset</button><button type="button" @click="reset='';confirmation=''">Cancel</button></form></article></section></template>
